25	// assertFileUnchanged 断言一次失败的 Open 没有回写数据文件。
26	func assertFileUnchanged(t *testing.T, dir string, before []byte) {
27		t.Helper()
28		after, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
29		if err != nil {
30			t.Fatalf("read file after open: %v", err)
31		}
32		if string(after) != string(before) {
33			t.Fatalf("打开失败不得覆盖或改写原数据文件")
34		}
35	}
36	
37	// assertOpenIDCorrupt 打开并断言：整次失败、nil 存放、ErrCorruptRecord，
38	// 错误信息包含所有 want 子串、且不包含任一 notWant 子串，原文件字节不变。
39	func assertOpenIDCorrupt(t *testing.T, dir string, want, notWant []string) {
40		t.Helper()
41		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
42		if err != nil {
43			t.Fatalf("read file before open: %v", err)
44		}
45		got, err := Open(dir)
46		if err == nil {
47			if got != nil {
48				got.Close()
49			}
50			t.Fatalf("编号有问题的记录必须让整次 Open 失败")
51		}
52		if got != nil {
53			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
54		}
55		if !errors.Is(err, ErrCorruptRecord) {
56			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
57		}
58		msg := err.Error()
59		for _, w := range want {
60			if !strings.Contains(msg, w) {
61				t.Fatalf("错误信息应包含 %q，实际 %q", w, msg)
62			}
63		}
64		// 哨兵错误自身的说明里也带有“不一致”“缺少状态”等字样，因此反向断言只
65		// 针对去掉哨兵前缀后的具体原因（与 open_missing_sampled_at_test.go 同款）。
66		detail := strings.TrimPrefix(msg, ErrCorruptRecord.Error())
67		for _, nw := range notWant {
68			if strings.Contains(detail, nw) {
69				t.Fatalf("具体错误原因不应包含 %q，实际 %q", nw, detail)
70			}
71		}
72		assertFileUnchanged(t, dir, before)
73	}
