75	// idCheckSample 构造一份除编号外内容完整的样品，便于证明测量与判定依据完整
76	// 不能代替编号正确。status 决定记录形态：confirmed 带完整达标判定，voided
77	// 带作废原因（待判定后直接作废、无历史依据）。
78	func idCheckSample(id string, status Status) *Sample {
79		smp := &Sample{
80			ID:           id,
81			PointID:      "P1",
82			SampledAt:    at(10, 0),
83			Measurements: []Measurement{{Item: openPH, Value: 7}},
84			Status:       status,
85		}
86		switch status {
87		case StatusConfirmed:
88			smp.Exceeded = false
89			smp.Results = []ItemResult{
90				{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
91			}
92		case StatusVoided:
93			smp.VoidReason = "录入信息有误"
94		}
95		return smp
96	}
