98	// sampleJSONWithIDToken 把样品序列化后，将其中的 "id":"..." 字段整体替换成
99	// idToken 给出的原始 JSON 片段，用于构造字段缺失、null、空串或 Unicode 转义
100	// 等 Go 结构体表达不出的写法。idToken 为空串表示整个字段缺失（连逗号一起去掉）。
101	// 调用方须保证 smp.ID 非空且为 "S1"，且 id 是序列化后的第一个字段。
102	func sampleJSONWithIDToken(t *testing.T, smp *Sample, idToken string) string {
103		t.Helper()
104		b, err := json.Marshal(smp)
105		if err != nil {
106			t.Fatalf("marshal sample: %v", err)
107		}
108		s := string(b)
109		if idToken == "" {
110			old := `"id":"` + smp.ID + `",`
111			if !strings.Contains(s, old) {
112				t.Fatalf("序列化结果中找不到编号字段 %q：%s", old, s)
113			}
114			return strings.Replace(s, old, "", 1)
115		}
116		old := `"id":"` + smp.ID + `"`
117		if !strings.Contains(s, old) {
118			t.Fatalf("序列化结果中找不到编号字段 %q：%s", old, s)
119		}
120		return strings.Replace(s, old, idToken, 1)
121	}
