350	func TestOpenIDProblemRejectsWholeFile(t *testing.T) {
351		dir := t.TempDir()
352		good := &Sample{
353			ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
354			Measurements: []Measurement{{Item: openPH, Value: 7}},
355			Status:       StatusConfirmed, Exceeded: false,
