401	}
402	
403	// 正常录入保存的数据两处编号始终一致：录入时带首尾空白会被整理，保存与重开后
404	// 编号、按点列表、最近有效结果、排序与作废资格都保持原有行为。
405	func TestOpenNormalFlowUnchangedAfterIDCheck(t *testing.T) {
406		s, dir := open(t)
407		mustPoint(t, s, "P1", "一号取水口")
408		mustLimit(t, s, "P1", openPH, 8, openEff())
409		// 录入时编号两侧带空白：正常流程整理为 S1 后保存。
410		mustSample(t, s, " S1 ", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
411		confirmed := mustConfirm(t, s, "S1")
412		if confirmed.ID != "S1" || !confirmed.Exceeded {
413			t.Fatalf("确认结果应保留整理后的编号与超标结论: %+v", confirmed)
414		}
415		if err := s.Close(); err != nil {
416			t.Fatalf("Close: %v", err)
417		}
418	
419		// 重新打开：编号、上限、历史结论与排序不变。
420		s2, err := Open(dir)
421		if err != nil {
422			t.Fatalf("正常流程保存的文件应正常打开: %v", err)
423		}
424		defer s2.Close()
425		list, err := s2.ListByPoint("P1")
426		if err != nil || len(list) != 1 || list[0].ID != "S1" {
427			t.Fatalf("按点列表应保留原样品 S1: %+v err=%v", list, err)
428		}
429		latest, ok, err := s2.LatestResult("P1")
430		if err != nil || !ok || latest.ID != "S1" {
431			t.Fatalf("最近有效结果应保留 S1: %+v ok=%v err=%v", latest, ok, err)
432		}
433		if len(latest.Results) != 1 || latest.Results[0].Limit != 8 || !latest.Results[0].Exceeded {
434			t.Fatalf("历史判定依据必须原样保留: %+v", latest)
435		}
436	
437		// 作废后重新打开：作废资格不变，最近有效结果跳过它。
438		if _, err := s2.Void("S1", "录入信息有误"); err != nil {
439			t.Fatalf("Void: %v", err)
440		}
441		if err := s2.Close(); err != nil {
442			t.Fatalf("Close: %v", err)
443		}
444		s3, err := Open(dir)
445		if err != nil {
446			t.Fatalf("作废后重新打开应正常: %v", err)
447		}
448		defer s3.Close()
449		if _, ok, err := s3.LatestResult("P1"); err != nil || ok {
450			t.Fatalf("已作废样品重开后仍应被最近有效结果跳过: ok=%v err=%v", ok, err)
451		}
452		if list, err := s3.ListByPoint("P1"); err != nil || len(list) != 1 || list[0].Status != StatusVoided {
453			t.Fatalf("作废记录与按点列表必须原样保留: %+v err=%v", list, err)
454		}
455	}
