433					Measurements: []Measurement{{Item: openPH, Value: 9}},
434					Status:       StatusPending,
435				},
436				// 待判定后作废：无历史依据。
437				"SV": {
438					ID: "SV", PointID: "P1", SampledAt: at(3, 0),
439					Measurements: []Measurement{{Item: openPH, Value: 9}},
440					Status:       StatusVoided, VoidReason: "录入信息有误",
441				},
442				// 已确认后作废：历史依据完整。
443				"SCV": {
