886			t.Fatalf("空样品集合应没有样品: %+v err=%v", list, err)
887		}
888	
889		// 已有数据文件但样品字段整体缺失（JSON null）。
890		raw := `{"points": {"P1": {"id": "P1", "name": "一号取水口"}}}`
891		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), []byte(raw), 0o644); err != nil {
892			t.Fatalf("write data file: %v", err)
893		}
894		s3, err := Open(dir)
895		if err != nil {
896			t.Fatalf("样品字段缺失的已有数据应正常打开: %v", err)
897		}
898		defer s3.Close()
899		if list, err := s3.ListByPoint("P1"); err != nil || len(list) != 0 {
900			t.Fatalf("样品字段缺失应没有样品: %+v err=%v", list, err)
901		}
902	}
903	
904	// assertOpenRejectsWholeFlag 断言整份超标标记与逐项结论矛盾时整次 Open 失败：
905	// 返回 nil 存放、ErrCorruptRecord、信息点名样品编号并说明与逐项结论不一致，
906	// 原文件字节不变；不要求信息里出现某个项目名。
907	func assertOpenRejectsWholeFlag(t *testing.T, dir, sampleID string) {
908		t.Helper()
909		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
910		if err != nil {
911			t.Fatalf("read file before open: %v", err)
912		}
913		got, err := Open(dir)
914		if err == nil {
915			if got != nil {
916				got.Close()
917			}
918			t.Fatalf("整份标记矛盾必须让整次 Open 失败，sample=%s", sampleID)
919		}
920		if got != nil {
921			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
922		}
923		if !errors.Is(err, ErrCorruptRecord) {
924			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
925		}
926		msg := err.Error()
927		if !strings.Contains(msg, sampleID) {
928			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
929		}
930		if !strings.Contains(msg, "逐项") {
931			t.Fatalf("错误信息应说明整份标记与逐项结论不一致，实际 %q", msg)
932		}
933		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
934		if rerr != nil {
935			t.Fatalf("read file after open: %v", rerr)
936		}
937		if string(after) != string(before) {
938			t.Fatalf("打开失败不得覆盖或改写原数据文件")
939		}
940	}
941	
942	// 测量值 9、上限 8 的判定却保存为达标：即使项目、测量值都对得上，也不能把
943	// 与依据矛盾的超标标记当成可信结论，整次打开失败并点名样品与项目。
944	func TestOpenItemExceededMarkedCompliant(t *testing.T) {
945		dir := t.TempDir()
946		writeDiskFile(t, dir, diskState{
947			Points: openPoints(),
948			Samples: map[string]*Sample{
949				"S1": {
950					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
951					Measurements: []Measurement{{Item: openPH, Value: 9}},
952					// 单项与整份都错成“达标”，单项矛盾必须先报出并点名项目。
953					Status: StatusConfirmed, Exceeded: false,
954					Results: []ItemResult{
955						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: false},
956					},
957				},
958			},
959		})
960		assertOpenRejects(t, dir, "S1", openPH, false)
961	}
962	
963	// 测量值 7、上限 8 的达标判定却保存为超标：反向标错同样拒绝。
964	func TestOpenItemCompliantMarkedExceeded(t *testing.T) {
965		dir := t.TempDir()
966		writeDiskFile(t, dir, diskState{
967			Points: openPoints(),
