971					Measurements: []Measurement{{Item: openPH, Value: 7}},
972					// 单项错成超标；整份标记与错误的单项保持一致，
973					// 证明只核对单项标记与保存依据这一条也足以拒绝。
974					Status: StatusConfirmed, Exceeded: true,
975					Results: []ItemResult{
976						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: true},
977					},
978				},
979			},
980		})
981		assertOpenRejects(t, dir, "S1", openPH, false)
982	}
