984	// 测量值恰好等于上限必须判为达标：保存成超标就是矛盾记录。
985	func TestOpenItemEqualLimitMarkedExceeded(t *testing.T) {
986		dir := t.TempDir()
987		writeDiskFile(t, dir, diskState{
