	if err != nil {
		t.Fatalf("中文编号的 Unicode 转义写法应正常读入: %v", err)
	}
	defer s.Close()
	list, err := s.ListByPoint("一号点")
	if err != nil || len(list) != 1 || list[0].ID != "S1" {
		t.Fatalf("应读入归属一号点的样品 S1: %+v err=%v", list, err)
	}
