		{"末尾制表但P1已登记", `"pointId":"P1\t"`, "P1\t"},
		{"前导空格且编号本身未登记", `"pointId":" P9 "`, " P9 "},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
