// 且原文件字节保持不变（不补登记采样点、不改写任何归属）。
func TestOpenPointProblemKeepsFileByteIdentical(t *testing.T) {
	dir := t.TempDir()
	writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
